import { View, Text, StyleSheet } from "react-native";
import { registerRootComponent } from "expo";

function App() {
  return (
    <View style={styles.screen}>
      <Text style={styles.title}>Shop.mn</Text>
      <Text style={styles.subtitle}>Монголын онлайн дэлгүүр</Text>
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, padding: 24, backgroundColor: "#f5f6f8" },
  title: { fontSize: 28, fontWeight: "bold", color: "#18181b" },
  subtitle: { fontSize: 16, color: "#52525b" },
});

registerRootComponent(App);
